未知関数 $y(x)$ とその導関数 $y'$ を含む等式を微分方程式という．$y'=f(x)g(y)$ の形のものは $\dfrac{y'}{g(y)}=f(x)$ と変形して両辺を $x$ で積分すれば解ける（変数分離形）．
\begin{enumerate}
\item $y'=2xy$，$y(0)=3$ をみたす関数 $y(x)$ を求めよ．
\item $t$ の関数 $y(t)$ が $y'=y(1-y)$，$y(0)=\dfrac{1}{2}$ をみたすとき，$y(t)$ を求めよ．
\item (2) の解について $\displaystyle\lim_{t\to\infty}y(t)$ を求めよ．
\end{enumerate}

定数 $a,b$ に対する微分方程式 $y''+ay'+by=0$ は，$y=e^{\lambda x}$ を代入して得られる2次方程式 $\lambda^2+a\lambda+b=0$（特性方程式）が異なる2実数解 $\lambda_1,\lambda_2$ をもつとき，一般解が $y=C_1e^{\lambda_1x}+C_2e^{\lambda_2x}$（$C_1,C_2$ は定数）で与えられる．
\begin{enumerate}
\item $y''-3y'+2y=0$ の特性方程式の解をすべて求めよ．
\item $y''-3y'+2y=0$，$y(0)=0$，$y'(0)=1$ をみたす解 $y(x)$ を求めよ．
\item (2) の解について $y(\log 2)$ の値を求めよ．
\end{enumerate}

行列 $A=\begin{pmatrix}2&1\\-1&0\end{pmatrix}$ に対し，連立微分方程式 $\boldsymbol{x}'(t)=A\boldsymbol{x}(t)$ を考える．
\begin{enumerate}
\item $A$ の固有値をすべて求めよ．
\item $e^{tA}$ のトレースと行列式を，それぞれ $t$ の式で求めよ．
\item 初期値 $\boldsymbol{x}(0)=\begin{pmatrix}1\\1\end{pmatrix}$ の解の第1成分 $x_1(t)$ を求めよ．
\end{enumerate}

微分方程式 $y''-2xy'+4y=0$ の解を $y=\displaystyle\sum_{k=0}^{\infty}c_kx^k$ の形で求める．
\begin{enumerate}
\item 係数の漸化式 $c_{k+2}=R(k)\,c_k$ における $R(k)$ を $k$ の式で求めよ．
\item $c_0=1,\ c_1=0$ のとき解は多項式になる．その多項式を求めよ．
\item $c_0=0,\ c_1=1$ のとき $c_3$ と $c_5$ を求めよ．
\end{enumerate}

\begin{enumerate}
\item 初期値問題 $y'=x+y$，$y(0)=1$ に対し，ピカールの逐次近似 $\varphi_0(x)=1$，$\varphi_{n+1}(x)=1+\displaystyle\int_0^x\bigl(s+\varphi_n(s)\bigr)\,ds$ を考える．$\varphi_2(x)$ を求めよ．
\item (1) の初期値問題の厳密解を $y(x)$ とするとき，$y(1)$ を求めよ．
\item 初期値問題 $y'=3y^{2/3}$，$y(0)=0$ は解を無数にもつことを示せ．また，これがリプシッツ条件をみたさないことと関係することを説明せよ．
\item $f(x,y)$ が $y$ についてリプシッツ定数 $L$ のリプシッツ条件をみたすとき，$y'=f(x,y)$ の2つの解 $y,z$ について $|y(x)-z(x)|\le|y(0)-z(0)|e^{L|x|}$ が成り立つことを示し，一意性を導け．
\end{enumerate}

$\boldsymbol{x}=(x_1,x_2)\in\mathbb{R}^2$ に対し $\|\boldsymbol{x}\|_1=|x_1|+|x_2|$，$\|\boldsymbol{x}\|_2=\sqrt{x_1^2+x_2^2}$，$\|\boldsymbol{x}\|_\infty=\max(|x_1|,|x_2|)$ と定める．また行列 $A$ に対し，$\|A\|_{\infty}=\max\{\|A\boldsymbol{x}\|_\infty:\|\boldsymbol{x}\|_\infty\le1\}$，$\|A\|_{1}=\max\{\|A\boldsymbol{x}\|_1:\|\boldsymbol{x}\|_1\le1\}$ と定める（作用素ノルム）．
\begin{enumerate}
\item $\boldsymbol{x}=(3,-4)$ に対し $\|\boldsymbol{x}\|_1$，$\|\boldsymbol{x}\|_2$，$\|\boldsymbol{x}\|_\infty$ を求めよ．
\item $A=\begin{pmatrix}1&2\\3&4\end{pmatrix}$ に対し $\|A\|_{\infty}$ を求めよ．
\item 同じ $A$ に対し $\|A\|_{1}$ を求めよ．
\end{enumerate}

区間 $[-\pi,\pi]$ 上の関数 $f,g$ に対し，内積を $\langle f,g\rangle=\displaystyle\int_{-\pi}^{\pi}f(x)g(x)\,dx$ と定める．$\langle f,g\rangle=0$ のとき $f$ と $g$ は直交するという．
\begin{enumerate}
\item $\langle\sin 3x,\sin 3x\rangle$ を求めよ．
\item $\langle\sin x,\sin 2x\rangle$ を求めよ．
\item 自然数 $n$ に対し $b_n=\dfrac{1}{\pi}\langle x,\sin nx\rangle$ を $n$ の式で求めよ．
\end{enumerate}

$g(t)=2t-1$ とし，$[0,1]$ 上の連続関数 $f$ に対し $\varphi(f)=\displaystyle\int_0^1g(t)f(t)\,dt$ と定める．
\begin{enumerate}
\item $C[0,1]$ に最大値ノルム $\|f\|_\infty=\max|f|$ を入れたとき，$\varphi$ の作用素ノルム $\|\varphi\|$ を求めよ．
\item $C[0,1]$ に $L^2$ ノルム $\|f\|_2=\left(\int_0^1|f|^2dt\right)^{1/2}$ を入れたとき，$\|\varphi\|$ を求めよ．
\item (1) の場合，$\|f\|_\infty\le1$ かつ $|\varphi(f)|=\|\varphi\|$ となる $f\in C[0,1]$ は存在しないことを示せ．
\end{enumerate}

$D$ を微分作用素 $Df=f'$ とする．
\begin{enumerate}
\item $C^1[0,1]\subset C[0,1]$ に最大値ノルム $\|f\|_\infty$ を入れ，$D:C^1[0,1]\to C[0,1]$ とみる．$f_n(x)=x^n$ に対し $\|Df_n\|_\infty/\|f_n\|_\infty$ を $n$ の式で求めよ．
\item $C^1[0,1]$ にノルム $\|f\|_{C^1}=\|f\|_\infty+\|f'\|_\infty$ を入れたとき，$D:(C^1,\|\cdot\|_{C^1})\to(C,\|\cdot\|_\infty)$ の作用素ノルムを求めよ．
\item (1) の $D$ は閉作用素である（$f_n\to f$，$f_n'\to h$（一様）なら $f\in C^1$，$f'=h$）．これと閉グラフ定理から，$(C^1[0,1],\|\cdot\|_\infty)$ がバナッハ空間でないことを導け．
\end{enumerate}

2変数関数 $u(x,t)$ についての方程式 $u_t+2u_x=0$（$u_t=\frac{\partial u}{\partial t}$，$u_x=\frac{\partial u}{\partial x}$）を移流方程式という．$x=x_0+2t$ に沿って $\dfrac{d}{dt}u(x_0+2t,t)=u_x\cdot2+u_t=0$ なので，$u$ は直線 $x-2t=\text{一定}$ の上で一定である．
\begin{enumerate}
\item $u(x,0)=e^{-x^2}$ のとき，$u(x,t)$ を求めよ．
\item $u(5,2)$ の値を求めよ．
\item 時刻 $t=3$ で $u(x,3)$ が最大となる $x$ を求めよ．
\end{enumerate}

平面の関数 $u(x,y)=x^3-3xy^2$ を考える．
\begin{enumerate}
\item $u$ が調和（$u_{xx}+u_{yy}=0$）であることを確かめ，$u+iv$ が正則となり $v(0,0)=0$ をみたす共役調和関数 $v(x,y)$ を求めよ．
\item 閉単位円板 $x^2+y^2\le1$ における $u$ の最大値を求めよ．
\item $\displaystyle\int_0^{2\pi}u(\cos\theta,\sin\theta)^2\,d\theta$ を求めよ．
\end{enumerate}

\begin{enumerate}
\item $x>0$ で $xu_x+2yu_y=0$，$u(1,y)=y$ をみたす $u(x,y)$ を求め，$u(2,8)$ の値を求めよ．
\item バーガース方程式 $u_t+uu_x=0$，$u(x,0)=-x$ の解を $0\le t<1$ で求めよ．
\item バーガース方程式 $u_t+uu_x=0$，$u(x,0)=\dfrac{1}{1+x^2}$ について，特性直線が初めて交わる時刻（解が滑らかでなくなる時刻）$T$ を求めよ．
\end{enumerate}
